class WeatherSystem:
    """
    A system to query weather data for a specific city with temperature unit conversion.
    """

    CELSIUS = 'celsius'
    FAHRENHEIT = 'fahrenheit'

    def __init__(self, city) -> None:
        self._city = city
        self._weather_list = {}
        self._temperature = None
        self._weather = None

    @property
    def city(self):
        return self._city

    def set_city(self, city):
        self._city = city

    @property
    def temperature(self):
        return self._temperature

    @temperature.setter
    def temperature(self, value):
        self._temperature = value

    @property
    def weather(self):
        return self._weather

    @weather.setter
    def weather(self, value):
        self._weather = value

    @property
    def weather_list(self):
        return self._weather_list.copy()

    def set_weather_list(self, weather_list):
        self._weather_list = weather_list

    def query(self, weather_list, tmp_units=CELSIUS):
        self._weather_list = weather_list
        if self.city not in weather_list:
            return False

        self._temperature = weather_list[self.city]['temperature']
        self._weather = weather_list[self.city]['weather']

        if weather_list[self.city]['temperature units'] != tmp_units:
            return self._convert_temperature(tmp_units)
        else:
            return self._temperature, self._weather

    def _convert_temperature(self, target_units):
        if target_units == self.CELSIUS:
            converted_temp = self._fahrenheit_to_celsius()
        elif target_units == self.FAHRENHEIT:
            converted_temp = self._celsius_to_fahrenheit()
        else:
            raise ValueError(f"Unknown temperature unit: {target_units}")

        return converted_temp, self._weather

    def celsius_to_fahrenheit(self):
        return self._celsius_to_fahrenheit()

    def fahrenheit_to_celsius(self):
        return self._fahrenheit_to_celsius()

    def _celsius_to_fahrenheit(self):
        return (self._temperature * 9 / 5) + 32

    def _fahrenheit_to_celsius(self):
        return (self._temperature - 32) * 5 / 9
